#include <iostream>

template <typename T>
T myMax(T a, T b) {
    return (a > b) ? a : b;
}

int main() {
    std::cout << myMax(10, 20) << std::endl;     // T deduced as int
    std::cout << myMax(5.5, 2.3) << std::endl;   // T deduced as double
}

